const routeDefault={tenants:'list',users:'list',tasks:'unified',billing:'config',models:'manage',settings:'site',deployments:'instances'};
function normalizeRoute(path){const parts=(path||'overview').split('/');let group=parts[0];if(group==='creations')group='tasks';if(!MODULES.some(m=>m.id===group))group='overview';let sub=parts[1]||routeDefault[group]||'',inner=parts[2]||'';if(!routes.some(r=>r.group===group&&r.sub===sub&&r.inner===inner)){sub=routeDefault[group]||'';inner=''}return {group,sub,inner,path:[group,sub,inner].filter(Boolean).join('/')}}
function currentDefaults(r){if(r.sub==='config')return 'batch';if(r.group==='billing'&&r.sub==='wallet')return 'products';if(r.group==='billing'&&r.sub==='cost')return 'calls';if(r.group==='models'&&r.sub==='manage')return 'models';if(r.group==='settings'&&r.sub==='site')return 'api';if(r.group==='tasks'&&r.sub==='unified')return 'new';if(r.group==='tenants'&&r.sub==='detail')return 'overview';return ''}
function innerTab(){return substate.route.inner||currentDefaults(substate.route)}
function activeKey(){return [substate.route.group,substate.route.sub,innerTab()].filter(Boolean).join('/')}
function filterState(key=activeKey()){return substate.filters[key]??=( {q:'',status:'all',page:1} )}
function routeHref(group,sub='',inner='',extra={}){const query=new URLSearchParams(extra);return [group,sub,inner].filter(Boolean).join('/')+(query.size?'?'+query:'')}
function currentQuery(){const r=substate.route;const q=new URLSearchParams();if(r.group==='tasks'&&['unified','history'].includes(r.sub)){if(state.taskQuery)q.set('q',state.taskQuery);if(state.taskStatus!=='all')q.set('status',state.taskStatus);if(state.taskProvider!=='all')q.set('provider',state.taskProvider);if(state.taskPage!==1)q.set('page',state.taskPage)}else if(r.group==='users'&&r.sub==='list'){if(state.userQuery)q.set('q',state.userQuery);if(state.userPlan!=='all')q.set('plan',state.userPlan);if(state.userPage!==1)q.set('page',state.userPage)}else{const f=filterState();if(f.q)q.set('q',f.q);if(f.status!=='all')q.set('status',f.status);if(f.page!==1)q.set('page',f.page)}if(r.group==='tenants'&&r.sub==='detail')q.set('tenant',substate.selectedTenant);return q}
function rememberRoute(){if(!substate.route)return;const q=currentQuery();substate.remember[state.page]=substate.route.path+(q.size?'?'+q:'')}
function syncAddress(){if(!substate.route)return;const q=currentQuery();const h='#'+substate.route.path+(q.size?'?'+q:'');if(location.hash!==h)history.replaceState(null,'',h);rememberRoute()}
function visitRoute(raw,replace=false){rememberRoute();const [path,query]=raw.split('?');const r=normalizeRoute(path);substate.route=r;state.page=r.group;const q=new URLSearchParams(query);const f=filterState();f.q=q.get('q')||'';f.status=q.get('status')||'all';f.page=Math.max(1,Number(q.get('page'))||1);if(r.group==='tasks'){state.taskQuery=f.q;state.taskStatus=f.status;state.taskProvider=q.get('provider')||'all';state.taskPage=f.page}if(r.group==='users'){state.userQuery=f.q;state.userPlan=q.get('plan')||'all';state.userPage=f.page}if(q.get('tenant'))substate.selectedTenant=q.get('tenant');ROOT.classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');if($('#detail-dialog').open)$('#detail-dialog').close();if($('#search-dialog').open)$('#search-dialog').close();if(location.hash!=='#'+raw)history[replace?'replaceState':'pushState'](null,'','#'+raw);substate.hydrating=true;render();substate.hydrating=false;window.scrollTo({top:0,behavior:'instant'});if(q.get('record'))openTask(q.get('record'))}
navigate=function(page){visitRoute(substate.remember[page]||routeHref(page,routeDefault[page]||''))};
renderNav=function(){const html=items=>items.map(m=>`<button class="nav-button ${state.page===m.id?'active':''}" data-page="${m.id}" aria-label="${m.label}" ${state.page===m.id?'aria-current="page"':''}>${icon(m.icon)}<span class="nav-label">${m.label}</span>${m.id==='notices'&&notices.some(n=>!n.read)?`<span class="nav-count">${notices.filter(n=>!n.read).length}</span>`:''}</button>`).join('');$('#primary-nav').innerHTML=html(MODULES.slice(0,6));$('#secondary-nav').innerHTML=html(MODULES.slice(6));$('#breadcrumb-current').textContent=MODULES.find(m=>m.id===state.page)?.label||'运营概览';$('#bell-dot').hidden=!notices.some(n=>!n.read)};
function moduleNav(){if(state.page==='tenants'&&substate.route.sub==='detail')return '';const m=MODULES.find(m=>m.id===state.page);return m.tabs.length?`<nav class="module-nav" aria-label="模块功能">${m.tabs.map(([sub,label,url])=>`<a href="#${m.id}/${sub}" data-route="${m.id}/${sub}" data-source-url="${esc(url)}" ${substate.route.sub===sub?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`:''}
function nestedNav(items,base,selected=innerTab()){return `<nav class="nested-nav" aria-label="子功能">${items.map(([id,n])=>`<a href="#${base}/${id}" data-route="${base}/${id}" ${base==='models/manage'&&id!=='library'?`data-model-tab="${id==='sources'?'suppliers':'models'}"`:''} ${selected===id?'aria-current="page"':''}>${n}</a>`).join('')}</nav>`}
function chrome(content,title,actions=''){return heading(title||MODULES.find(m=>m.id===state.page).label,actions)+moduleNav()+content+footer()}
const button=(text,action,primary=false)=>`<button class="button ${primary?'primary':''}" data-sub-action="${action}">${esc(text)}</button>`;
function pageActions(){if(state.page==='tasks'&&substate.route.sub==='unified'&&innerTab()==='new')return `<button class="button" data-action="export-tasks">${icon('download')}导出记录</button><button class="button" data-action="refresh">${icon('refresh-cw')}刷新</button>`;if(state.page==='users'&&substate.route.sub==='list')return `<button class="button" data-action="export-users">${icon('download')}导出用户</button>`;if(state.page==='billing'&&substate.route.sub==='ledger')return `<button class="button" data-action="export-billing">${icon('download')}导出流水</button>`;return ''}
