function tableState(key){return filterState(activeKey()+'::'+key)}
function collection(key,{rows,header=true,filter=true,extra='',add=false}={}){const def=readTables[key];if(!def)throw Error('Missing collection '+key);const fs=tableState(key);if(substate.hydrating)Object.assign(fs,filterState());if(rows)def.liveRows=rows;else delete def.liveRows;substate.currentTable=key;const statuses=[...new Set((def.liveRows||def.rows).map(r=>r.status||r.entry).filter(Boolean))];return `${header?`<div class="section-toolbar"><h2>${def.title}</h2><div class="surface-actions">${add?`<button class="button primary" data-create-row="${key}">${icon('plus')}新增</button>`:''}${extra}<button class="button" data-collection-export="${key}">${icon('download')}导出</button></div></div>`:''}<section class="panel" data-collection="${key}">${filter?`<div class="filters"><label class="input-wrap search-input">${icon('search')}<input class="collection-query" data-collection-query="${key}" value="${esc(fs.q)}" aria-label="搜索${def.title}" placeholder="搜索${def.title}"></label>${statuses.length?`<select class="select" data-collection-status="${key}" aria-label="${def.title}状态"><option value="all">全部状态</option>${statuses.map(s=>`<option value="${esc(s)}" ${fs.status===s?'selected':''}>${esc(subLabels[s]||statusName[s]||s)}</option>`).join('')}</select>`:''}<span class="filter-spacer"></span><button class="button ghost" data-collection-reset="${key}">重置</button></div>`:''}<div id="collection-${key}">${collectionResults(key)}</div></section>`}
function filteredCollection(key){const d=readTables[key],f=tableState(key);return (d.liveRows||d.rows).filter(r=>(f.status==='all'||(r.status||r.entry)===f.status)&&JSON.stringify(r).toLowerCase().includes(f.q.toLowerCase()))}
function cellHtml(row,col){const v=row[col.key];if(typeof v==='boolean')return v?'开启':'关闭';if(col.format==='status')return tag(v);if(col.format==='money')return Number(v).toFixed(2);if(col.format==='optional')return v==null?'未确认':esc(v);return esc(v??'—')}
function collectionResults(key){const d=readTables[key],f=tableState(key),list=filteredCollection(key),pages=Math.max(1,Math.ceil(list.length/8));f.page=Math.min(f.page,pages);return `<div class="table-wrap"><table class="table ${d.cols.length>6?'wide-table':''}"><thead><tr>${d.cols.map(col=>`<th class="${['number','money'].includes(col.format)?'numeric':''}">${col.label}</th>`).join('')}<th></th></tr></thead><tbody>${list.slice((f.page-1)*8,f.page*8).map((r)=>`<tr data-record-id="${esc(r.id)}">${d.cols.map(col=>`<td class="${['number','money'].includes(col.format)?'numeric':col.format==='wrap'?'cell-wrap':''}">${cellHtml(r,col)}</td>`).join('')}<td><button class="button link" data-row-table="${key}" data-row-id="${esc(r.id)}">${d.actionLabel||'查看'} ${icon('chevron-right')}</button></td></tr>`).join('')||`<tr><td colspan="${d.cols.length+1}">${empty('没有匹配的记录')}</td></tr>`}</tbody></table></div><div class="table-footer"><span>共 ${list.length} 条 · 第 ${f.page} / ${pages} 页</span><div class="pagination"><button class="page-number" data-collection-page="${key}:${f.page-1}" ${f.page===1?'disabled':''} aria-label="上一页">${icon('chevron-left')}</button>${Array.from({length:pages},(_,i)=>`<button class="page-number ${f.page===i+1?'active':''}" data-collection-page="${key}:${i+1}">${i+1}</button>`).join('')}<button class="page-number" data-collection-page="${key}:${f.page+1}" ${f.page===pages?'disabled':''} aria-label="下一页">${icon('chevron-right')}</button></div></div>`}
function updateCollection(key){$('#collection-'+key).innerHTML=collectionResults(key);const fs=tableState(key);Object.assign(filterState(),fs);syncAddress()}
function factPairs(entries){return `<dl class="detail-keyvalues">${entries.map(([n,v])=>`<div><dt>${esc(n)}</dt><dd>${esc(v??'未记录')}</dd></div>`).join('')}</dl>`}
function fieldsForm(key,title,fields,{actions='',description=''}={}){const values=substate.drafts[key]||{};const input=f=>{const [name,label,type,value,opts]=f;const v=values[name]??value;if(type==='checkbox')return `<div class="field"><label class="checkbox-line"><input type="checkbox" name="${name}" ${v?'checked':''}>${label}</label></div>`;return `<div class="field ${type==='textarea'?'wide':''}"><label for="f-${name}">${label}</label>${type==='select'?`<select id="f-${name}" name="${name}">${opts.map(x=>`<option value="${esc(x)}" ${String(v)===String(x)?'selected':''}>${esc(subLabels[x]||x)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${name}" name="${name}" maxlength="2000">${esc(v)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" ${type==='number'?'min="0" max="1000000" step="any"':''} ${type==='password'?'autocomplete="off"':''} value="${type==='password'?'':esc(v)}" ${type!=='password'?'required':''} maxlength="200">`}</div>`};return `<section class="panel form-panel"><h2 style="margin-bottom:22px">${title}</h2>${description?`<div class="notice-box" style="margin-bottom:18px">${description}</div>`:''}<form data-draft-form="${key}"><div class="form-grid">${fields.map(input).join('')}</div><div class="form-actions"><span class="form-status" role="status">${values.__saved?'已保存预览草稿':''}</span><span class="filter-spacer"></span>${actions}<button class="button" type="button" data-reset-draft="${key}">重置</button><button class="button primary" type="submit">保存草稿</button></div></form></section>`}

