function galleryView(kind){const key=kind==='tryon'?'tryon':'images';const fs=filterState();const list=(kind==='tryon'?templatesFixture:tasks.filter(t=>t.status==='done')).filter(t=>`${t.title||t.name} ${t.user||''}`.toLowerCase().includes(fs.q.toLowerCase()));return `<div class="gallery-controls"><div class="filters"><label class="input-wrap search-input">${icon('search')}<input data-gallery-query="${key}" aria-label="搜索${kind==='tryon'?'素材':'图片'}" placeholder="搜索${kind==='tryon'?'素材':'图片、用户'}" value="${esc(fs.q)}"></label><span class="filter-spacer"></span><span class="subpage-row-count">${list.length} ${kind==='tryon'?'份素材':'张图片'}</span></div></div><div class="gallery-grid" id="gallery-results">${list.map(t=>`<button class="gallery-item" ${kind==='tryon'?`data-row-table="templates" data-row-id="${t.id}"`:`data-task="${t.id}"`}><div class="gallery-art">${artwork(t.art)}</div><div class="gallery-caption"><strong>${esc(t.title||t.name)}</strong><span><span>${esc(t.user||t.category)}</span><span>${kind==='tryon'?'演示素材':'1024 × 1024'}</span></span></div></button>`).join('')||empty('没有匹配的素材')}</div>`}
function modelView(){const sub=substate.route.sub,inner=innerTab();if(sub==='manage'){return nestedNav([['models','模型映射'],['sources','上游来源'],['library','供应商模型库']],'models/manage')+(inner==='library'?collection('metadata'):(inner==='sources'?`<div class="section-toolbar"><h2>上游来源</h2><button class="button primary" data-action="add-provider">${icon('plus')}添加供应商</button></div>${supplierCards()}`:modelMapping()))}if(sub==='balances')return collection('balances');if(sub==='config')return configView();if(sub==='health')return `<div class="surface-actions" style="margin-bottom:17px">${button('巡检设置','inspection-settings')}${button('演示巡检结果','inspect-demo')}</div>${collection('modelHealth')}`;return collection('quality')}
function modelMapping(){return `<div class="section-toolbar"><h2>模型映射</h2><div class="surface-actions">${link('models/manage/library','供应商模型库','button')}${button('新增公开模型','new-public-model',true)}</div></div><section class="panel"><div class="filters"><label class="input-wrap search-input">${icon('search')}<input id="model-query" aria-label="搜索模型" placeholder="搜索模型名称" value="${esc(state.modelQuery)}"></label><select class="select" id="model-provider" aria-label="模型供应商筛选"><option value="all">全部供应商</option>${providers.map(p=>`<option ${state.modelProvider===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select class="select" id="model-status" aria-label="模型状态筛选"><option value="all">全部状态</option><option value="enabled" ${state.modelStatus==='enabled'?'selected':''}>已启用</option><option value="disabled" ${state.modelStatus==='disabled'?'selected':''}>已停用</option></select></div><div id="model-results"></div></section>`}
function configView(){const tab=innerTab();const nav=nestedNav(CONFIG_TABS,`${state.page}/config`);let body='';if(tab==='imagePreset')body=fieldsForm('config/imagePreset','APIMart 默认预设',forms.imagePreset);if(tab==='batch')body=modelMapping();if(tab==='business')body=collection('tariffs');if(tab==='providers')body=`<div class="section-toolbar"><h2>供应商</h2><button class="button primary" data-action="add-provider">${icon('plus')}添加供应商</button></div>${supplierCards()}`;if(tab==='upstreamModels')body=collection('upstreams',{add:true});if(tab==='publicModels')body=collection('publicModels',{add:true});if(tab==='pools')body=fieldsForm('config/pools','混合路由',forms.pools);if(tab==='bindings')body=fieldsForm('config/bindings','默认用途',forms.bindings);if(tab==='simulation')body=simulationView();if(tab==='history')body=collection('releases');return nav+body}
function simulationView(){return `<section class="panel form-panel"><h2 style="margin-bottom:20px">路由模拟</h2><form id="route-simulation"><div class="form-grid"><div class="field"><label for="sim-feature">功能</label><select id="sim-feature"><option>图片生成</option><option>参考图编辑</option></select></div><div class="field"><label for="sim-resolution">分辨率</label><select id="sim-resolution"><option>1K</option><option selected>2K</option><option>4K</option></select></div><div class="field"><label for="sim-provider">供应商</label><select id="sim-provider"><option value="all">全部供应商</option>${providers.map(p=>`<option>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="sim-quantity">生成张数</label><input id="sim-quantity" type="number" value="1" min="1" max="100" required></div></div><div class="form-actions"><button class="button primary">运行本地模拟</button></div></form><div id="simulation-result" class="detail-section">${simulationResult('all',1)}</div></section>`}
function simulationResult(provider,count,resolution='2K'){const eligible=models.filter(m=>m.kind!=='视频'&&m.enabled&&(provider==='all'||m.provider===provider)&&(m.params.includes(resolution)||(resolution==='1K'&&m.params.includes('1024'))));return `<h3>候选通道</h3><div class="plain-list">${eligible.map(m=>`<div><span>${esc(m.provider)} / ${esc(m.name)}</span><strong>${m.price*count} 积分</strong></div>`).join('')||'<div>没有符合条件的通道</div>'}</div>`}
function walletView(){const tab=innerTab();let body='';if(tab==='prices')body=collection('tariffs');if(tab==='costs')body=collection('supplierCosts');if(tab==='rules')body=fieldsForm('wallet/rules','特殊定价规则',forms.pricingRule);if(tab==='products')body=collection('packs',{add:true});if(tab==='credits')body=fieldsForm('wallet/credits','赠送与总开关',forms.credits);if(tab==='history')body=collection('releases');if(tab==='operations')body=collection('operationReview');return nestedNav(WALLET_TABS,'billing/wallet')+body}
function costView(){const tab=innerTab();let body=tab==='calls'?collection('costCalls'):tab==='reconcile'?collection('reconcile'):tab==='accounts'?fieldsForm('cost/accounts','供应商账户',forms.account):`<div class="summary-row">${[['调用次数','128'],['成功交付','118'],['确认成本','6.24 USD'],['待确认成本','4 笔']].map(([n,v])=>`<div class="pill-stat"><label>${n}</label><strong>${v}</strong></div>`).join('')}</div>${collection('supplierCosts')}`;return nestedNav(COST_TABS,'billing/cost')+body}
function pricingEstimate(){return `<section class="panel form-panel"><h2 style="margin-bottom:22px">定价测算</h2><form id="pricing-estimate"><div class="form-grid"><div class="field"><label for="estimate-model">模型</label><select id="estimate-model">${models.slice(0,4).map(m=>`<option value="${m.id}">${m.name}</option>`).join('')}</select></div><div class="field"><label for="estimate-count">图片数量</label><input id="estimate-count" type="number" min="1" max="10000" value="10" required></div><div class="field"><label for="estimate-cost">单张采购成本（元）</label><input id="estimate-cost" type="number" min="0" step="0.01" value="0.30" required></div><div class="field"><label for="estimate-credit">每积分售价（元）</label><input id="estimate-credit" type="number" min="0" step="0.01" value="0.10" required></div></div><div class="form-actions"><button class="button primary">计算</button></div></form><div class="calc-result" id="estimate-result">${estimateResult(6,10,.3,.1)}</div></section>`}
function estimateResult(price,count,cost,unit){return [['预计积分',price*count],['采购成本',`¥ ${(count*cost).toFixed(2)}`],['售价减成本',`¥ ${(count*(price*unit-cost)).toFixed(2)}`]].map(([n,v])=>`<div><label>${n}</label><strong>${v}</strong></div>`).join('')}
function billingView(){const sub=substate.route.sub;if(sub==='config')return configView();if(sub==='wallet')return walletView();if(sub==='orders')return collection('orders');if(sub==='ledger')return baseContent(V1.billingPage);if(sub==='prices')return collection('priceMatrix');if(sub==='cost')return costView();return pricingEstimate()}
function tenantView(){const sub=substate.route.sub;if(sub==='list')return `<div class="summary-row">${[['租户',tenantsFixture.length],['正常',tenantsFixture.filter(t=>t.status==='active').length],['即将到期',1]].map(([n,v])=>`<div class="pill-stat"><label>${n}</label><strong>${v}</strong></div>`).join('')}</div>${collection('tenants',{add:true})}`;if(sub==='teams')return collection('teams',{add:true});if(sub==='access')return collection('teamAccess');const t=tenantsFixture.find(t=>t.id===substate.selectedTenant)||tenantsFixture[0];substate.selectedTenant=t.id;const tab=innerTab();let body='';if(tab==='overview')body=`<section class="panel details-panel"><h2>企业资料</h2>${factPairs([['企业 ID',t.id],['负责人',t.owner],['负责人账号',t.email],['权益名称',t.plan],['有效成员',`${t.members} / ${t.seats}`],['授权期限',t.expires],['授权状态',subLabels[t.status]],['创建时间',t.created]])}<div class="surface-actions"><button class="button" data-edit-table="tenants" data-edit-id="${t.id}">编辑企业资料</button>${link(`tenants/detail/creations?tenant=${t.id}`,'查看创作记录','button')}</div></section>`;if(tab==='members')body=collection('tenantMembers',{add:true})+`<div style="margin-top:21px">${collection('roles',{add:true})}</div>`;if(tab==='entitlement')body=fieldsForm('tenant/'+t.id+'/entitlement','套餐与额度',[['plan','权益名称','text',t.plan],['seats','成员席位','number',t.seats],['expires','授权期限','date',t.expires],['credits','共享额度（积分）','number',t.credits],...featureList.map((name,i)=>['feature'+i,name,'checkbox',i<5])]);if(tab==='creations')body=`<div class="table-wrap panel">${taskTable(tasks.filter((_,i)=>i%3===0),true)}</div>`;if(tab==='billing')body=`<div class="summary-row"><div class="pill-stat"><label>可用积分</label><strong>${t.credits}</strong></div><div class="pill-stat"><label>已结算</label><strong>428</strong></div><div class="pill-stat"><label>预占</label><strong>12</strong></div></div><div class="table-wrap panel">${taskTable(tasks.filter((_,i)=>i%4===0),true)}</div>`;if(tab==='audit')body=collection('management',{rows:auditFixture.slice(0,5)});return `<div class="section-toolbar"><div class="tenant-identity"><span class="avatar">${t.name[0]}</span><h2>${esc(t.name)}</h2>${tag(t.status)}</div>${link('tenants/list','返回租户列表','tenant-back')}</div>${nestedNav(TENANT_TABS,'tenants/detail').replace(/(href="#|data-route=")(tenants\/detail\/[^"?]+)"/g,(m,prefix,p)=>`${prefix}${p}?tenant=${t.id}"`)}${body}`}
function permissionView(){return collection('permissions')}
function settingsView(){const sub=substate.route.sub;if(sub==='management')return collection('management');if(sub==='access')return collection('accessLog');const tab=innerTab();let body='';if(tab==='brand')body=baseContent(V1.settingsPage);if(['api','auth','pages','account-credits','legacy-deploy'].includes(tab))body=fieldsForm('settings/'+tab,SETTINGS_TABS.find(x=>x[0]===tab)[1],forms[tab]);if(tab==='usage')body=collection('usage');if(tab==='templates')body=collection('templates',{add:true});if(tab==='tryon')body=galleryView('tryon');if(tab==='prompts')body=collection('prompts',{add:true});if(tab==='cardkeys')body=collection('cardkeys',{add:true});return nestedNav(SETTINGS_TABS,'settings/site')+body}
function healthView(){return `<div class="summary-row">${[['执行队列','15'],['待收尾父任务','2'],['未知活动','1'],['近 5 分钟 tick','20']].map(([n,v])=>`<div class="pill-stat"><label>${n}</label><strong>${v}</strong></div>`).join('')}</div><section class="panel details-panel"><h2>运行状态</h2><div class="inspection-list">${[['Worker','running','最近 tick 已完成'],['恢复扫描','unknown','1 条未知活动待核查'],['领域租约','active','4 个执行中任务'],['媒体处理','active','队列正常']].map(([n,s,t])=>`<div class="inspection-item"><span>${n}</span><span class="subtle">${t}</span>${tag(s)}</div>`).join('')}</div><div class="detail-links">${link('tasks/unified/new?status=queued','查看排队任务')}${link('models/health','查看模型巡检')}${link('deployments/instances','查看部署实例')}</div></section><div style="margin-top:20px">${collection('modelHealth')}</div>`}
function deploymentView(){const tab=substate.route.sub||'instances';let body=tab==='instances'?collection('instances',{add:true}):tab==='commands'?collection('commands'):tab==='grants'?collection('grants',{add:true}):tab==='releases'?collection('policies'):collection('management');return nestedNav([['instances','实例管理'],['commands','管理指令'],['grants','运维授权'],['releases','版本跟随'],['audit','审计记录']],'deployments',tab)+body}
render=function(){if(!substate.route){substate.route=normalizeRoute(state.page)}renderNav();let content;if(state.page==='overview')content=overview();else if(state.page==='notices')content=noticePage();else{let body=state.page==='tasks'?creationView():state.page==='models'?modelView():state.page==='users'?(substate.route.sub==='permissions'?permissionView():baseContent(V1.userPage)):state.page==='billing'?billingView():state.page==='tenants'?tenantView():state.page==='settings'?settingsView():state.page==='health'?healthView():deploymentView();content=chrome(body,undefined,pageActions())}$('#main-content').innerHTML=content;$('#main-content').dataset.route=activeKey();ROOT.classList.toggle('compact',state.compact);if($('#task-results'))renderTaskResults();if($('#model-results'))renderModelResults();if($('#user-results'))renderUserResults();if($('#billing-results'))renderBillingResults();$$('.collection-inline-tabs a').forEach(a=>a.setAttribute('aria-current',a.dataset.route.endsWith('/'+innerTab())?'page':'false'));hydrate();renderChart()};

readTables.historicJobs={title:'历史业务任务',rows:tasks.slice(0,14).map((t,i)=>({...t,id:`demo-historic-${600+i}`,kind:['旧生图','画布任务','视频任务','批处理'][i%4],date:`2026-10-${21-i%5}`,originalId:t.id})),cols:[c('id','历史任务'),c('kind','任务类型'),c('user','用户'),c('model','冻结模型'),c('status','业务状态','status'),c('credits','实际落账','number'),c('date','提交日期')],action:'historic'};
readTables.legacyCreations={title:'历史生成',rows:tasks.slice(0,10).map((t,i)=>({...t,id:`demo-legacy-cr-${901+i}`,date:`2026-10-${14-i%4}`,originalId:t.id,source:i%2?'旧画布':'旧生图页'})),cols:[c('id','创作记录'),c('title','内容'),c('source','来源'),c('user','用户'),c('status','状态','status'),c('date','日期')],action:'historic'};

function openGenericRecord(key,id){const def=readTables[key],row=(def.liveRows||def.rows).find(r=>String(r.id)===String(id));if(!row)return;
 if(def.action==='tenant')return visitRoute(`tenants/detail/overview?tenant=${row.id}`);
 if(def.action==='permissions')return openPermissions(row);
 if(['call','quality','review'].includes(def.action))return openEvidenceTask(row,def.title);
 if(def.action==='historic')return openEvidenceTask({...row,id:row.originalId},def.title);
 if(def.action==='conversation')return openConversation(row);
 if(def.action==='userUsage')return openUser(row.id);
 let body=factPairs(def.cols.map(col=>[col.label,['status'].includes(col.format)?subLabels[row[col.key]]||statusName[row[col.key]]||row[col.key]:row[col.key]]));
 if(def.action==='teamAccess')body+=`<div class="detail-section"><h3>授权范围</h3>${factPairs([['入口','企业工作台'],['授权主体',row.name],['负责人',row.owner],['策略版本','demo-policy-v1'],['生效方式','保存预览草稿'],['用户限制','保留原账号归属']])}</div>`;
 if(def.action==='team')body+=`<div class="detail-section"><h3>团队与子账号</h3><div class="plain-list">${users.slice(0,4).map(u=>`<div><span>${esc(u.name)}</span><button class="button link" data-user="${u.id}">查看成员</button></div>`).join('')}</div><div class="detail-links">${link('tenants/detail/members?tenant='+row.tenant,'成员与权限')}</div></div>`;
 if(def.action==='cost')body+=`<div class="detail-section"><h3>原调用关联</h3>${factPairs([['原任务',row.task],['供应商 request_id',row.request],['受理状态',tasks.find(t=>t.id===row.task)?.status||'未确认'],['已交付张数',row.delivered],['原币金额',row.amount==null?'未确认':row.amount+' '+row.currency],['费用状态',subLabels[row.status]]])}<button class="button" data-task="${row.task}">查看原任务</button></div>`;
 if(def.action==='order')body+=`<div class="detail-section"><h3>付款与到账</h3>${factPairs([['订单金额','¥ '+row.amount.toFixed(2)],['订单冻结积分',row.credits],['支付渠道',row.channel],['确认状态',subLabels[row.status]],['实际到账',row.status==='paid'?row.credits:row.status==='unpaid'?'0':'已退款'],['交易号',row.status==='unpaid'?'未记录':'demo-payment-'+row.id]])}</div>`;
 if(def.action==='audit')body+=`<div class="detail-section"><h3>变更前后</h3>${factPairs([['变更前',row.before],['变更后',row.after],['操作原因',row.reason]])}</div>`;
 if(def.action==='release')body+=`<div class="detail-section"><h3>版本差异</h3><div class="plain-list"><div><span>默认图像通道</span><span>APIMart → APIB</span></div><div><span>输出规格</span><span>1K → 2K</span></div></div></div>`;
 if(def.action==='metadata')body+=`<div class="detail-section"><h3>参数与采购依据</h3>${factPairs([['公开模型',row.name],['Wire Model ID',row.sub],['规格依据','演示供应商文档'],['人工覆盖','保留'],['采购币种','USD'],['核对日期','2026-10-27']])}</div>`;
 if(def.action==='balance')body+=`<div class="detail-section"><h3>测量记录</h3>${factPairs([['资金余额',row.accountBalance],['Key 额度',row.keyQuota],['测量类型',row.kind],['读取时间',row.time]])}</div>`;
 if(def.action==='reconcile')body+=`<div class="detail-section"><h3>补查记录</h3>${factPairs([['统计窗口',row.date],['差额归属','未分配给用户'],['查询依据','原供应账单'],['本地原始记录','demo-cost-1']])}<button class="button" data-row-table="costCalls" data-row-id="demo-cost-1">查看调用链</button></div>`;
 if(def.action==='modelHealth')body+=`<div class="detail-section"><h3>巡检结果</h3>${factPairs([['供应商',row.provider],['巡检状态',subLabels[row.status]],['产物状态',row.status==='healthy'?'已保存演示图片':'无已确认产物'],['费用','仅演示，不发起模型调用']])}</div>`;
 if(def.action==='instance')body+=`<div class="detail-section"><h3>实例管理</h3><div class="detail-links">${link('users/list','用户与权限')}${link('deployments/commands','管理指令')}${link('deployments/grants','运维授权')}${link('deployments/releases','版本跟随')}${link('deployments/audit','审计记录')}</div></div>`;
 if(def.action==='template')body=`<div class="output-art">${artwork(row.art||0)}</div>`+body;
 const foot=`<small>演示记录</small><div class="surface-actions">${def.editable?`<button class="button primary" data-edit-table="${key}" data-edit-id="${esc(row.id)}">编辑草稿</button>`:''}<button class="button" data-action="close-detail">关闭</button></div>`;
 openDialog(dialogShell(def.title+'详情',body,foot),'collection',id);
}
function openEvidenceTask(t,title){V1.openTask(t.id);if(!$('#detail-dialog').open)return;$('#dialog-title').textContent=title+'详情';const call=readTables.calls.rows.find(r=>r.id===t.id);const extra=document.createElement('section');extra.className='detail-section';extra.innerHTML=`<h3>调用与参数证据</h3>${factPairs([['前端展示模型',call?.model],['平台模型 ID','public-'+t.id],['实际请求模型',call?.wire],['上游确认模型',call?.actual],['供应商通道',call?.provider],['模型 / 计费版本','v32 / v18'],['输入 Token','0'],['输出 Token','0']])}`;$('#detail-dialog .dialog-content').append(extra)}
function openConversation(row){const body=`<div class="detail-title"><h3>${esc(row.title)}</h3><span class="chip">${esc(row.source)}</span></div>${factPairs([['用户',row.user],['模型',row.model],['存储条目',row.messages],['Token',row.tokens]])}<div class="conversation-thread"><div class="message user"><strong>${esc(row.user)}</strong>帮我为新品香氛设计一套主图方案，画面保持简洁。</div><div class="message"><strong>Naumi</strong>建议采用暖灰背景，以瓶身材质和柔和侧光为重点。第一张展示产品主体，第二张展示场景，第三张展示包装细节。</div><div class="message user"><strong>${esc(row.user)}</strong>先查看第一张图的方案。</div><div class="message"><strong>Naumi</strong>方案已保存在对应创作记录中。</div></div><div class="detail-links">${link('tasks/unified/new?record=demo-img-2801','查看关联创作')}</div>`;openDialog(dialogShell('对话详情',body,`<small>演示对话</small><button class="button" data-action="close-detail">关闭</button>`),'conversation',row.id)}
function openPermissions(row){const allowed=(row.allowed||'').split('、');const body=`<div class="user-info" style="margin-bottom:22px"><span class="avatar">${row.name[0]}</span><div>${esc(row.name)}<small>${row.account}</small></div></div><form id="permission-editor" data-user-id="${row.id}"><div class="field"><label for="permission-mode">授权模式</label><select id="permission-mode" name="mode"><option ${row.policy==='默认权限'?'selected':''}>默认权限</option><option ${row.policy==='自定义'?'selected':''}>自定义</option></select></div><div class="permission-grid">${featureList.map((name,i)=>`<label class="permission-cell"><input type="checkbox" name="feature" value="${name}" ${allowed.includes(name)?'checked':''}>${name}</label>`).join('')}</div></form>`;openDialog(dialogShell('功能权限',body,`<small>仅保存预览权限</small><button class="button primary" form="permission-editor">保存权限</button>`),'permissions',row.id)}
function editRecord(key,id){const def=readTables[key];const existing=id?(def.liveRows||def.rows).find(r=>r.id===id):null;if(!def)return;const row=existing||Object.fromEntries(def.cols.map(col=>[col.key,col.format==='number'||col.format==='money'?0:col.format==='status'?'draft':'']));const fields=def.cols.filter(c=>c.key!=='id').map(col=>{let type=typeof row[col.key]==='boolean'?'checkbox':['number','money'].includes(col.format)?'number':col.key.includes('email')||col.key==='account'?'email':col.key==='expires'||col.key==='expiry'?'date':col.format==='wrap'?'textarea':col.format==='status'?'select':'text';let options=col.key==='status'?['active','suspended','draft']:col.key==='entry'?['active','suspended']:['draft','active'];return [col.key,col.label,type,row[col.key]??'',options]});if(key==='prompts')fields.find(f=>f[0]==='content')[2]='textarea';const body=fieldsForm('record/'+key+'/'+(id||'new'),existing?'编辑'+def.title:'新增'+def.title,fields);openDialog(dialogShell(existing?'编辑记录':'新增记录',body,`<small>仅保存本地演示数据</small><button class="button" data-action="close-detail">关闭</button>`),'record',{key,id});substate.genericDialog={key,id}}
function showModelExtras(id){const m=models.find(x=>x.id===id);if(!m)return;const target=$('#model-form');if(!target)return;const opts=(list,v)=>list.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');target.insertAdjacentHTML('beforeend',`<details class="detail-section"><summary>供应通道与分辨率</summary><div class="field-pair" style="margin-top:16px"><div class="field"><label for="extra-weight">通道权重</label><input id="extra-weight" name="weight" type="number" min="1" max="100" value="${m.weight||100}"></div><div class="field"><label for="extra-resolutions">分辨率选项</label><input id="extra-resolutions" name="resolutions" value="${esc(m.resolutions||m.params)}"></div></div></details>${m.kind==='视频'?`<details class="detail-section" open><summary>视频能力</summary><div class="field-pair" style="margin-top:16px"><div class="field"><label for="extra-seconds">视频时长（秒）</label><input id="extra-seconds" name="seconds" type="number" min="1" max="30" value="${m.seconds||5}"></div><div class="field"><label for="extra-audio">音频</label><select id="extra-audio" name="audio">${opts(['关闭','开启'],m.audio?'开启':'关闭')}</select></div></div></details>`:`<details class="detail-section"><summary>图像高级参数</summary><div class="field-pair" style="margin-top:16px"><div class="field"><label for="extra-format">输出格式</label><select id="extra-format" name="format">${opts(['PNG','JPEG','WebP'],m.format||'PNG')}</select></div><div class="field"><label for="extra-background">背景</label><select id="extra-background" name="background">${opts(['自动','透明','不透明'],m.background||'自动')}</select></div></div></details><details class="detail-section"><summary>视频能力</summary><div class="field"><label for="extra-video">视频能力状态</label><select id="extra-video"><option>当前为图像模型，不支持视频</option></select></div></details>`}`)}
const originalModelDialog=openModel;
openModel=function(id){originalModelDialog(id);showModelExtras(id)};
const originalTaskDialog=openTask;
openTask=function(id){originalTaskDialog(id);if(!$('#detail-dialog').open)return;const t=tasks.find(x=>x.id===id);const content=$('#detail-dialog .dialog-content');content.insertAdjacentHTML('beforeend',`<details class="detail-section"><summary>输入素材与处理后输入</summary><div class="output-art" style="margin-top:14px">${artwork((t.art+1)%3)}<span class="output-tag">演示输入素材</span></div><div class="chips"><span class="chip">上传原图</span><span class="chip">参考图</span></div></details><details class="detail-section"><summary>关联子任务</summary>${factPairs([['子任务 ID','demo-child-'+id],['子任务状态',statusName[t.status]],['报价积分',t.credits||t.hold||6],['释放预占',t.status==='failed'?6:0]])}</details><details class="detail-section"><summary>技术与来源信息</summary>${factPairs([['来源','本地预览'],['冻结 scope','个人'],['模型版本','v32'],['计费版本','v18']])}</details>`)};

function subAction(action){if(action==='inspection-settings'){openDialog(dialogShell('巡检设置',fieldsForm('inspection/settings','模型健康巡检',forms.modelInspection)),'settings','inspection');return}if(action==='inspect-demo'){readTables.modelHealth.rows.filter(m=>m.enabled).forEach(m=>{m.status='healthy';m.last='10:50:00';m.reason='演示巡检产物已保存'});render();toast('已更新演示巡检结果');return}if(action==='new-public-model')return editRecord('publicModels',null)}
document.addEventListener('click',event=>{
 const target=event.target.closest('button,a');if(!target)return;const d=target.dataset;
 if(d.route){event.preventDefault();event.stopImmediatePropagation();visitRoute(d.route);return}
 if(target.matches('.brand')){event.preventDefault();event.stopImmediatePropagation();visitRoute('overview');return}
 if(d.rowTable){event.preventDefault();event.stopImmediatePropagation();openGenericRecord(d.rowTable,d.rowId);return}
 if(d.editTable){event.preventDefault();event.stopImmediatePropagation();editRecord(d.editTable,d.editId);return}
 if(d.createRow){event.preventDefault();event.stopImmediatePropagation();editRecord(d.createRow,null);return}
 if(d.subAction){event.preventDefault();event.stopImmediatePropagation();subAction(d.subAction);return}
 if(d.collectionPage){const idx=d.collectionPage.lastIndexOf(':');const key=d.collectionPage.slice(0,idx);tableState(key).page=Number(d.collectionPage.slice(idx+1));updateCollection(key);return}
 if(d.collectionReset){const f=tableState(d.collectionReset);f.q='';f.status='all';f.page=1;Object.assign(filterState(),f);render();syncAddress();return}
 if(d.collectionExport){const def=readTables[d.collectionExport];csvExport('naumi-demo-'+d.collectionExport+'.csv',def.cols.map(c=>c.label),filteredCollection(d.collectionExport).map(r=>def.cols.map(c=>r[c.key]??'')));return}
 if(d.resetDraft){delete substate.drafts[d.resetDraft];if(d.resetDraft.startsWith('record/'))editRecord(substate.genericDialog.key,substate.genericDialog.id);else if($('#detail-dialog').open&&d.resetDraft==='inspection/settings')subAction('inspection-settings');else render();return}
 if(d.action==='go-suppliers'){event.preventDefault();event.stopImmediatePropagation();visitRoute('models/manage/sources');return}
 if(d.action==='export-tasks'||d.action==='refresh'||d.taskStatus||d.taskPage||d.userPage||d.action==='clear-task-filters'||d.action==='clear-users'){queueMicrotask(syncAddress)}
},true);
document.addEventListener('input',event=>{const t=event.target;if(t.dataset.collectionQuery){const key=t.dataset.collectionQuery;const f=tableState(key);f.q=t.value;f.page=1;updateCollection(key)}if(t.dataset.galleryQuery){filterState().q=t.value;const pos=t.selectionStart;render();const fresh=$('[data-gallery-query]');fresh.focus();fresh.setSelectionRange(pos,pos);syncAddress()}if(['task-query','user-query'].includes(t.id))syncAddress()});
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.collectionStatus){const key=t.dataset.collectionStatus;tableState(key).status=t.value;tableState(key).page=1;updateCollection(key)}if(['task-provider','user-plan'].includes(t.id))syncAddress()});
document.addEventListener('submit',event=>{
 const form=event.target;
 if(form.dataset.draftForm){event.preventDefault();const key=form.dataset.draftForm;const data={};for(const el of form.elements){if(!el.name||el.type==='password')continue;data[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value}data.__saved=true;substate.drafts[key]=data;
  if(key.startsWith('record/')){const {key:tableKey,id}=substate.genericDialog;const def=readTables[tableKey];if(id){Object.assign(def.rows.find(r=>r.id===id),data)}else{const row={...data,id:'demo-'+tableKey+'-'+(def.rows.length+100),art:0};def.rows.push(row)}closeDetail();render()}
  else if(key.startsWith('tenant/')&&key.endsWith('/entitlement')){const tenant=tenantsFixture.find(t=>t.id===substate.selectedTenant);Object.assign(tenant,{plan:data.plan,seats:data.seats,expires:data.expires,credits:data.credits});$('.form-status',form).textContent='已保存预览草稿'}
  else $('.form-status',form).textContent='已保存预览草稿';toast('已保存预览草稿');return;
 }
 if(form.id==='permission-editor'){event.preventDefault();const row=users.find(u=>u.id===form.dataset.userId);row.policy=form.elements.mode.value;row.allowed=new FormData(form).getAll('feature').join('、');closeDetail();render();toast('预览权限已保存')}
 if(form.id==='route-simulation'){event.preventDefault();$('#simulation-result').innerHTML=simulationResult($('#sim-provider').value,Number($('#sim-quantity').value),$('#sim-resolution').value);toast('本地模拟完成，未请求供应商')}
 if(form.id==='pricing-estimate'){event.preventDefault();const m=models.find(m=>m.id===$('#estimate-model').value);$('#estimate-result').innerHTML=estimateResult(m.price,Number($('#estimate-count').value),Number($('#estimate-cost').value),Number($('#estimate-credit').value))}
 if(form.id==='provider-form'&&!$('#detail-dialog').open)visitRoute('models/manage/sources');
});
document.addEventListener('submit',event=>{if(event.target.id==='model-form'){const m=models.find(m=>m.id===state.dialogId);if(m){const fd=new FormData(event.target);m.weight=Number(fd.get('weight'));m.resolutions=String(fd.get('resolutions'));m.format=String(fd.get('format'));m.background=String(fd.get('background'));if(m.kind==='视频'){m.seconds=Number(fd.get('seconds'));m.audio=fd.get('audio')==='开启'}}}},true);
document.addEventListener('click',event=>{const d=event.target.closest('button,a')?.dataset;if(d&&(d.taskStatus||d.taskPage||d.userPage||['clear-task-filters','clear-users'].includes(d.action)))syncAddress()});
window.addEventListener('popstate',()=>visitRoute(location.hash.slice(1)||'overview',true));
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'overview';if(next.split('?')[0]!==substate.route?.path)visitRoute(next,true)});
const initialRoute=location.hash.slice(1)||'overview';
Object.assign(SOURCE_ALIASES,{
 '/admin?view=settings&section=users':'users/list','/admin?view=settings&section=artworks':'tasks/images',
 '/admin?view=settings&section=ledger':'billing/ledger','/admin?view=settings&section=credits':'billing/wallet/credits',
 '/admin?view=settings&section=wallet':'billing/wallet/products','/admin?view=settings&section=recharge':'billing/wallet/products',
 '/admin?view=settings&section=deploy':'deployments/instances','/admin?view=settings&section=models':'models/manage/models',
 '/admin?view=settings&section=model-config':'models/config',
 ...Object.fromEntries(['login','payment','payments','pay','wechat','smtp'].map(k=>['/admin?view=settings&tab='+k,'settings/site/auth'])),
 ...Object.fromEntries(['branding','site'].map(k=>['/admin?view=settings&tab='+k,'settings/site/brand'])),
 '/admin?view=settings&tab=page':'settings/site/pages','/admin?view=settings&tab=template':'settings/site/templates',
 '/admin?view=settings&tab=prompt':'settings/site/prompts','/admin?view=settings&tab=cardkey':'settings/site/cardkeys',
 '/admin?view=settings&tab=redeem':'settings/site/cardkeys'
});
window.NAUMI_PREVIEW_MANIFEST={modules:MODULES,routes,aliases:SOURCE_ALIASES,fixture:true,productionRequests:false};
visitRoute(initialRoute,true);
